"""Pure, offline view of the registered 2kHz sine comparison summary.

No file I/O, native decoding or numerical work occurs on import. No field map is
inferred from scalar statistics. The sole parent supplies completed JSON.
"""
from __future__ import annotations
import json
import math

SCENARIOS=('human_2000_2010_sine','human_3000_3030_sine','legacy_3000_3030_sine')
LABELS={'human_2000_2010_sine':'문헌 대체모델 · 2000/2010 Hz',
        'human_3000_3030_sine':'같은 문헌 대체모델 · 3000/3030 Hz',
        'legacy_3000_3030_sine':'기존 팬텀 가정 · 3000/3030 Hz'}


def build_artifact(summary):
    if not isinstance(summary,dict)or summary.get('schema')!='task1-minimum-sine-frequency-comparison-v1':
        raise ValueError('Registered sine comparison summary required')
    scenarios=summary.get('scenarios')
    if not isinstance(scenarios,dict)or any(k not in scenarios for k in SCENARIOS):
        raise ValueError('All three explicitly evaluated sine scenarios are required')
    if summary.get('actual_new_native_conditions')!=1 or summary.get('actual_new_RHS')!=4:
        raise ValueError('Exact one-condition/four-RHS comparison receipt required')
    for key in SCENARIOS:
        s=scenarios[key]
        if s.get('waveform')!='two-tone sine'or not isinstance(s.get('statistics'),dict)or not isinstance(s.get('electrical'),dict):
            raise ValueError('Actual sine statistics/electrical results required')
    payload=dict(summary=summary,scenario_order=list(SCENARIOS),labels=LABELS)
    encoded=json.dumps(payload,ensure_ascii=False,allow_nan=False,separators=(',',':')).replace('<','\\u003c')
    manifest=dict(schema='task1-experiment-sine-summary-view-v1',run_id=summary.get('run_id'),case_id=summary.get('case_id'),
        source_schema=summary['schema'],actual_new_native_conditions=1,actual_new_RHS=4,view_new_PDE=0,
        scenarios=list(SCENARIOS),field_maps_fabricated=False,native_probe_Vpp_newly_evaluated=False,
        chart_scope='fixed1Vpp each; common axis per chart across three scenarios',
        normalization_scope='Separate comparator-derived sameV/equal current bookkeeping/equal sourcepower/joint eight numerical burden caps; no physiological limits',
        actual_human_thoracoabdominal_validation=False,Windows_saved=False)
    return dict(html=TEMPLATE.replace('__DATA__',encoded),manifest=manifest)


def build(summary):
    """Return standalone HTML; parent owns all input pins, IO and publication."""
    return build_artifact(summary)['html']


